import { UpdateNotificationPreferencesResolver } from './update-notification-preferences.resolver';

/** See mutations/task/create-task/create-task.module.ts's comment: SessionService reaches this resolver
 * through the app's one global SessionModule registration, not through an import here. */
@Module({
  imports: [CqrsModule],
  providers: [UpdateNotificationPreferencesResolver],
})
export class UpdateNotificationPreferencesSingleMutationModule extends ConfigurableModuleClass {}

import { Test, TestingModule } from '@nestjs/testing';
import { CommandBus } from '@nestjs/cqrs';
import { validate } from 'class-validator';
import { SessionRecord, SessionService } from '@modules/bussiness/session';
import { UpdateNotificationPreferencesCommand } from '@modules/bussiness/notify';
import {
  SessionExpiredException,
  SessionNotFoundException,
} from '@modules/shared/exceptions';
import { GraphqlRequestLike } from '../../../session-actor.adapter';
import { UpdateNotificationPreferencesInput } from './graphql-types/input';
import { UpdateNotificationPreferencesResolver } from './update-notification-preferences.resolver';

describe('UpdateNotificationPreferencesResolver (fr.notify.unsubscribe / data.notify.preference)', () => {
  let moduleRef: TestingModule;
  let resolver: UpdateNotificationPreferencesResolver;
  let execute: jest.Mock;
  let findActive: jest.Mock;

  const req = (token?: string): GraphqlRequestLike => ({
    headers: token === undefined ? {} : { authorization: `Bearer ${token}` },
  });
  const activeSession = (personId = 'person-1') =>
    new SessionRecord('tok-1', personId, new Date(), new Date(Date.now() + 60_000));
  const input = (overrides: Partial<UpdateNotificationPreferencesInput>): UpdateNotificationPreferencesInput =>
    Object.assign(new UpdateNotificationPreferencesInput(), { channel: 'email', ...overrides });

  beforeEach(async () => {
    execute = jest.fn();
    findActive = jest.fn();
    moduleRef = await Test.createTestingModule({
      providers: [
        UpdateNotificationPreferencesResolver,
        { provide: CommandBus, useValue: { execute } },
        { provide: SessionService, useValue: { findActive } },
      ],
    }).compile();
    resolver = moduleRef.get(UpdateNotificationPreferencesResolver);
  });

  afterEach(() => moduleRef.close());

  it('dispatches the command with caller actorId and every preference field the input carries', async () => {
    findActive.mockResolvedValue(activeSession());
    execute.mockResolvedValue({ channel: 'email', unsubscribed: true, digestWindowMinutes: 60 });

    const result = await resolver.updateNotificationPreferences(
      req('tok-1'),
      input({ unsubscribed: true, digestWindowMinutes: 60 }),
    );

    expect(findActive).toHaveBeenCalledWith('tok-1');
    const command = execute.mock.calls[0][0];
    expect(command).toBeInstanceOf(UpdateNotificationPreferencesCommand);
    expect(command.params).toEqual({
      actorId: 'person-1',
      channel: 'email',
      unsubscribed: true,
      digestWindowMinutes: 60,
    });
    expect(result).toEqual({ channel: 'email', unsubscribed: true, digestWindowMinutes: 60 });
  });

  it('forwards a partial patch with omitted fields left undefined for the handler to keep', async () => {
    findActive.mockResolvedValue(activeSession());
    execute.mockResolvedValue({ channel: 'email', unsubscribed: false, digestWindowMinutes: null });

    const result = await resolver.updateNotificationPreferences(req('tok-1'), input({}));

    expect(execute.mock.calls[0][0].params).toEqual({
      actorId: 'person-1',
      channel: 'email',
