 * fr.plan.upgrade's exception flow: "The webhook arrives with an invalid signature; it is ignored, the
 * subscription stays pending, and no money is treated as received." A failed authorization check answers
 * 200 with `{ignored: true}` rather than propagating the exception as a 4xx/5xx - SePay's own retry
 * policy should not be given a reason to keep re-delivering a request this endpoint has already decided
 * to ignore, and nothing about an unauthenticated delivery should be observable to whoever sent it.
 */
@Controller('webhooks/sepay')
export class SepayWebhookController {
  constructor(
    private readonly sepayClient: SepayClient,
    private readonly commandBus: CommandBus,
  ) {}

  @Post()
  @HttpCode(HttpStatus.OK)
  async handle(
    @Headers('authorization') authorization: string | undefined,
    @Body() body: SepayWebhookBody,
  ): Promise<{ ignored: boolean } | ConfirmPaymentCommandResult> {
    try {
      this.sepayClient.assertWebhookAuthorized(authorization);
    } catch (error) {
      if (error instanceof PlanWebhookUnauthorizedException) {
        return { ignored: true };
      }
      throw error;
    }
    return this.commandBus.execute<ConfirmPaymentCommand, ConfirmPaymentCommandResult>(
      new ConfirmPaymentCommand({
        gatewayIntentId: body.id,
        outcome: body.status,
        periodEnd: body.periodEnd ? new Date(body.periodEnd) : undefined,
      }),
    );
  }
}

import { ConfigurableModuleBuilder } from '@nestjs/common';

export const { ConfigurableModuleClass, OPTIONS_TYPE } = new ConfigurableModuleBuilder().setExtras(
  { isGlobal: false },
  (definition, extras) => ({ ...definition, global: extras.isGlobal }),
).build();

import { DynamicModule, Module } from '@nestjs/common';
import { CqrsModule } from '@nestjs/cqrs';
import { SepayModule } from '@modules/integrations/sepay';
import { ConfigurableModuleClass, OPTIONS_TYPE } from './sepay-webhook.module-definition';
import { SepayWebhookController } from './sepay-webhook.controller';

/**
 * Mounts SepayWebhookController, mirroring HealthModule's own placement (a plain HTTP door registered
 * beside its own feature, not under `modules/platform`). `SepayModule.register()` is imported because
 * the controller injects `SepayClient` directly (not through the CommandBus); `PlanModule` is not
 * imported here - `ConfirmPaymentCommand`'s handler is discovered by @nestjs/cqrs's app-wide explorer
 * once PlanModule is anywhere in the compiled module graph (it is, from app.module.ts), the same reason
 * create-task.module.ts never imports TaskModule to reach CreateTaskHandler.
 */
@Module({})
export class SepayWebhookModule extends ConfigurableModuleClass {
  static register(options: typeof OPTIONS_TYPE = {}): DynamicModule {
    const base = super.register(options);
    return {
      ...base,
      imports: [CqrsModule, SepayModule.register()],
      controllers: [SepayWebhookController],
    };
  }
}
